import React, { useState } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { UserPlus, BarChart3, Camera, Users } from 'lucide-react';

const AdminPage = ({ userName = 'المدير', onNavigate }) => {
  // Page view state
  const [activePage, setActivePage] = useState('dashboard'); // 'dashboard', 'addUser', 'subscribers'

  // Example data
  const [requests, setRequests] = useState([
    { id: 1, name: 'محمد علي', status: 'معلق' },
    { id: 2, name: 'سارة أحمد', status: 'مكتمل' },
    { id: 3, name: 'خالد يوسف', status: 'معلق' },
  ]);
  const [subscribers, setSubscribers] = useState(125);

  // Handler for buttons
  const handleChangePage = (page) => setActivePage(page);

  return (
    <div className="flex flex-col min-h-screen bg-gray-50" dir="rtl">
      <Header onNavigate={onNavigate} title="لوحة الإدارة" />

      <main className="flex flex-1 p-6 gap-6">
        {/* Left section - dynamic content */}
        <section className="flex-1 bg-white rounded-xl shadow p-6 transition-all duration-300">
          {activePage === 'dashboard' && (
            <>
              <h2 className="text-2xl font-bold mb-4">مرحباً {userName}</h2>
              <h3 className="text-xl font-semibold mb-4">طلبات المستخدمين</h3>

              <table className="w-full border-collapse text-right">
                <thead>
                  <tr className="bg-gray-200">
                    <th className="border p-2">الاسم</th>
                    <th className="border p-2">الحالة</th>
                  </tr>
                </thead>
                <tbody>
                  {requests.map((req) => (
                    <tr key={req.id} className="hover:bg-gray-100 transition-colors">
                      <td className="border p-2">{req.name}</td>
                      <td className="border p-2">
                        <span
                          className={`px-2 py-1 rounded text-white ${
                            req.status === 'معلق' ? 'bg-yellow-500' : 'bg-green-500'
                          }`}
                        >
                          {req.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {activePage === 'addUser' && (
            <div className="text-center">
              <h2 className="text-2xl font-bold mb-4">إضافة مستخدم جديد</h2>
              <form className="max-w-md mx-auto space-y-4">
                <input
                  type="text"
                  placeholder="الاسم الكامل"
                  className="w-full p-3 border rounded-lg"
                />
                <input
                  type="email"
                  placeholder="البريد الإلكتروني"
                  className="w-full p-3 border rounded-lg"
                />
                <input
                  type="password"
                  placeholder="كلمة المرور"
                  className="w-full p-3 border rounded-lg"
                />
                <button className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold hover:bg-blue-700">
                  إضافة المستخدم
                </button>
              </form>
            </div>
          )}

          {activePage === 'subscribers' && (
            <div className="text-center">
              <h2 className="text-2xl font-bold mb-4">معلومات المشتركين</h2>
              <p className="text-lg mb-2">عدد المشتركين الحاليين:</p>
              <p className="text-4xl font-bold text-blue-600">{subscribers}</p>
              <button
                className="mt-6 bg-green-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-green-700"
              >
                تحديث المعلومات
              </button>
            </div>
          )}
        </section>

        {/* Right sidebar */}
        <aside className="w-64 flex-shrink-0 flex flex-col gap-4">
          <button
            onClick={() => handleChangePage('addUser')}
            className={`flex items-center gap-2 p-3 rounded font-bold transition-colors ${
              activePage === 'addUser' ? 'bg-blue-700 text-white' : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            <UserPlus /> إضافة مستخدم
          </button>

          <button
            onClick={() => handleChangePage('subscribers')}
            className={`flex items-center gap-2 p-3 rounded font-bold transition-colors ${
              activePage === 'subscribers'
                ? 'bg-blue-700 text-white'
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            <Users /> معلومات المشتركين
          </button>

          <div
            className="bg-white p-4 rounded-xl shadow text-center cursor-pointer hover:shadow-lg transition"
            onClick={() => handleChangePage('subscribers')}
          >
            <h4 className="font-semibold mb-2">عدد المشتركين</h4>
            <p className="text-2xl font-bold text-blue-600">{subscribers}</p>
          </div>
        </aside>
      </main>

      <Footer />
    </div>
  );
};

export default AdminPage;
